/* Recording controls: four destinations and one guided step at a time. */
const recordingNavigationBase={handle};
const recordingSteps={
 1:[['Public request','Guest Portals','Fill in the public form and submit your group request.','public'],['Review request','Admin App','Open the new request, review availability and confirm it.','request'],['Prepare quote','Admin App','Convert to Group Block, select inventory and rates, then prepare and send the quote.','quote'],['Review & pay','Email Inbox','Open the organizer email link, review documents, e-sign and pay the deposit.','organizer-email'],['Confirm booking','Admin App','Review the signed booking, convert it to a reservation and confirm.','group']],
 2:[['Organizer invitation','Email Inbox','Open the organizer email and follow the secure link.','organizer-email'],['Allocate rooms','Guest Portals','Assign guests to blocked rooms and send invitations, or share the group code.','rooms'],['Guest invitation','Email Inbox','Select a guest inbox and open their invitation or group booking link.','guest-email'],['Choose & pay','Guest Portals','Confirm an assigned room, or choose an available room using the group code, then pay.','guest-room'],['Manage reservations','Admin App','Open an individual reservation and manage its room or availability.','reservations']],
 3:[['Organizer email','Email Inbox','Open the organizer secure link from the email.','organizer-email'],['Organizer portal','Guest Portals','Manage rooms, guests, invoices, documents, schedule and meals using the portal menu.','overview'],['Guest email','Email Inbox','Select a guest inbox and open the guest secure link.','guest-email'],['Guest portal','Guest Portals','Review the stay, room, schedule, documents and charges, then request an activity or service.','stay'],['Staff review','Admin App','Review the new service request and confirm or decline it.','requests'],['Guest update','Guest Portals','See the confirmed service, staff message and updated charges in the guest portal.','charges']],
 4:[['Guest arrival','Cashier App','Scan the demo guest pass, confirm the stay and complete check-in.','arrival'],['Take an order','Cashier App','Choose a reservation, add food or drinks, then check out and charge to the room.','cashier'],['Connected record','Admin App','Open the reservation to see accommodation, payments, orders, services and signatures together.','record'],['Guest charges','Guest Portals','Review the purchases and outstanding balance in the guest portal.','charges'],['Check-out','Cashier App','Open the reservation, settle its remaining balance and complete check-out.','cashier']]
};
function recordingVideo(){return v2Active()?Number(state.ui.video||2):1;}
function recordingStep(){const v=recordingVideo();return Math.min(recordingSteps[v].length-1,Math.max(0,state.ui.recordingSteps?.[v]||0));}
function recordingDestination(){if(state.ui.app==='guest')return state.ui.guest==='mailbox'?'email':'guest';return state.ui.admin?.startsWith('pos')?'cashier':'admin';}
demoBar=function(){if(state.ui.recording)return '';const v=recordingVideo(),steps=recordingSteps[v],i=recordingStep(),step=steps[i],destination=recordingDestination();const apps=[['Guest Portals','guest'],['Admin App','admin'],['Cashier App','cashier'],['Email Inbox','email']];return '<div class="demo-bar recording-navigation '+(state.ui.recording?'compact':'')+'"><div class="switcher" role="group" aria-label="Switch demo app">'+apps.map(([name,id])=>'<button data-action="demo-app-'+id+'" class="'+(destination===id?'active':'')+'" aria-pressed="'+(destination===id)+'">'+name+'</button>').join('')+'</div><div class="demo-tools">'+(state.ui.recording?'': '<div class="recording-videos" role="group" aria-label="Select demo video">'+[1,2,3,4].map(n=>button('Video '+n,'demo-video-'+n,n===v?'video-active':'')).join('')+'</div>')+button(state.ui.recording?'Show steps':'Recording mode','recording')+(state.ui.recording?'':button('Reset demo','reset'))+'</div></div>'+(state.ui.recording?'':'<section class="recording-guide" aria-label="Video walkthrough"><div class="recording-step-copy"><label for="recording-step">Video '+v+' · Step '+(i+1)+' of '+steps.length+'</label><select id="recording-step" name="recording-step">'+steps.map((s,j)=>'<option value="'+j+'" '+(i===j?'selected':'')+'>'+(j+1)+'. '+s[0]+' · '+s[1]+'</option>').join('')+'</select><p>'+step[2]+'</p></div><div class="recording-step-actions">'+button('← Previous','demo-step-prev','',i===0)+button('Open this step','demo-step-open','primary')+button('Next →','demo-step-next','',i===steps.length-1)+'</div></section>');};
function recordingOpenStep(index){const v=recordingVideo(),steps=recordingSteps[v],step=steps[index];requireState(step,'Step not found.');requireState(!modal,'Close the current dialog before opening another step.');const route=step[3];if(['request','quote'].includes(route))requireState(state.request,'Submit the public request before opening this step.');if(route==='group')requireState(state.quote?.paid,'Complete the organizer signature and deposit first.');if(['rooms','overview','guest-room','reservations','stay','requests','charges','arrival','cashier','record'].includes(route))requireState(v2Active(),'Start Video 2, 3 or 4 to open this step.');(state.ui.recordingSteps??={})[v]=index;save();
 if(route==='public')return navigate('guest','form');
 if(route==='request')return navigate('admin','request');
 if(route==='quote')return navigate('admin',state.quote?'block':'request');
 if(route==='group')return navigate('admin',state.reservation?'reservation':'block');
 if(route==='organizer-email')return openMailbox('organizer');
 if(route==='guest-email')return openMailbox('priya');
 if(route==='rooms'||route==='overview')return openOrganizerPortal(route);
 if(route==='guest-room')return openGuestPortal('room');
 if(route==='stay'||route==='charges')return openGuestPortal(route);
 if(route==='reservations')return navigate('admin','individual-list');
 if(route==='requests')return navigate('admin','service-list');
 if(route==='arrival'){ops().arrivalStage='scan';return navigate('admin','pos-arrival');}
 if(route==='cashier')return navigate('admin','pos-list');
 if(route==='record'){pickup().currentId=activePosGuest().id;return navigate('admin','individual-detail');}
}
handle=function(a,el){try{
 if(a.startsWith('demo-app-')){requireState(!modal,'Close the current dialog before switching apps.');const app=a.slice(9);if(app==='email')return openMailbox();if(app==='cashier'){requireState(v2Active(),'Select Video 4 to load the confirmed group and open Cashier App.');return navigate('admin','pos-list');}if(app==='admin')return navigate('admin',state.ui.admin?.startsWith('pos')?'individual-list':state.ui.admin||'list');return navigate('guest',state.ui.guest==='mailbox'?(v2Active()?'organizer-portal':'form'):state.ui.guest||'form');}
 if(a.startsWith('demo-video-')){const n=Number(a.slice(11));requireState(!modal,'Close the current dialog before switching videos.');(state.ui.recordingSteps??={})[n]=0;if(n===1){if(v2Active())return recordingNavigationBase.handle('v2-video1',el);state.ui.video=1;save();render();return;}if(n===2){state.ui.video=2;return recordingNavigationBase.handle('v2-start',el);}return recordingNavigationBase.handle('cx-video'+n,el);}
 if(a==='demo-step-open'||a==='demo-step-next'||a==='demo-step-prev')return recordingOpenStep(recordingStep()+(a==='demo-step-next'?1:a==='demo-step-prev'?-1:0));
 return recordingNavigationBase.handle(a,el);
 }catch(error){toast(error.message,true);}};
document.addEventListener('change',event=>{if(event.target.name==='recording-step')try{recordingOpenStep(Number(event.target.value));}catch(error){toast(error.message,true);render();}});
render();
